package es.foco.next.ui;
import static org.junit.Assert.*;
import android.content.*;import android.media.*;
import es.foco.next.runtime.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @LooperMode(LooperMode.Mode.PAUSED)
public class QuietMusicTest {
 private Context c;private AudioManager audio;private QuietMusic q;private org.robolectric.android.controller.ServiceController<CalmAudioService> service;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();ReflectionHelpers.callStaticMethod(CalmAudio.class,"resetForTests");c.getSharedPreferences("foco-soundscape",0).edit().clear().commit();audio=c.getSystemService(AudioManager.class);Shadows.shadowOf(audio).setNextFocusRequestResponse(AudioManager.AUDIOFOCUS_REQUEST_GRANTED);ShadowMediaPlayer.setMediaInfoProvider(source->new ShadowMediaPlayer.MediaInfo(120000,0));q=new QuietMusic(c,()->{});}
 private void start(){service=Robolectric.buildService(CalmAudioService.class).create();assertEquals(android.app.Service.START_NOT_STICKY,service.get().onStartCommand(new Intent(),0,1));}
 @After public void close(){q.stop();if(service!=null)service.destroy();ReflectionHelpers.callStaticMethod(CalmAudio.class,"resetForTests");}
 @Test public void autoplaysOnlyForVisibleOwnerAndStopsOnExit(){assertFalse(CalmAudio.wanted());q.enter();assertTrue(CalmAudio.pending());start();assertTrue(q.playing());q.stop();assertFalse(CalmAudio.active());assertFalse(CalmAudio.wanted());}
 @Test public void focusLossStopsWithoutAutomaticallyRestarting(){q.enter();start();assertTrue(q.playing());Shadows.shadowOf(audio).getLastAudioFocusRequest().listener.onAudioFocusChange(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);assertFalse(q.playing());q.enter();assertFalse(CalmAudio.pending());assertNotNull(Shadows.shadowOf(audio).getLastAbandonedAudioFocusRequest());}
 @Test public void deniedAudioFocusDoesNotPlay(){Shadows.shadowOf(audio).setNextFocusRequestResponse(AudioManager.AUDIOFOCUS_REQUEST_FAILED);q.enter();start();assertFalse(q.playing());assertFalse(CalmAudio.pending());}
 @Test public void muteSurvivesAnotherVisit(){q.enter();start();q.toggle();assertFalse(CalmAudio.enabled(c));assertFalse(q.playing());q.stop();QuietMusic next=new QuietMusic(c,()->{});try{next.enter();assertFalse(CalmAudio.wanted());assertFalse(CalmAudio.pending());}finally{next.stop();}}
 @Test public void surfacesShareOnePlayerWithoutRestarting(){q.enter();start();MediaPlayer first=ReflectionHelpers.getField(service.get(),"player");QuietMusic overlay=new QuietMusic(c,()->{},true);try{overlay.enter();assertSame(first,ReflectionHelpers.getField(service.get(),"player"));q.stop();assertTrue(overlay.playing());overlay.stop();assertFalse(CalmAudio.active());}finally{overlay.stop();}}
 @Test public void completionAlternatesTheTwoProvidedTracks(){q.enter();start();MediaPlayer first=ReflectionHelpers.getField(service.get(),"player");int before=CalmAudio.track();Shadows.shadowOf(first).invokeCompletionListener();assertEquals((before+1)%2,CalmAudio.track());assertNotSame(first,ReflectionHelpers.getField(service.get(),"player"));assertTrue(q.playing());}
 @Test public void respectsOtherPlayerOnEntryButIntervenesAtBlock(){Shadows.shadowOf(audio).setIsMusicActive(true);q.enter();assertFalse(CalmAudio.pending());QuietMusic block=new QuietMusic(c,()->{},true);try{block.enter();assertTrue(CalmAudio.pending());start();assertTrue(block.playing());}finally{block.stop();}}
 @Test public void callsPreventAutomaticPlayback(){audio.setMode(AudioManager.MODE_IN_COMMUNICATION);q.enter();assertFalse(CalmAudio.pending());QuietMusic block=new QuietMusic(c,()->{},true);try{block.enter();assertFalse(CalmAudio.pending());}finally{block.stop();}}
 @Test public void blockUsesTemporaryExclusiveFocusWithoutChangingDeviceVolume(){int volume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);q.enter();start();MediaPlayer same=ReflectionHelpers.getField(service.get(),"player");QuietMusic block=new QuietMusic(c,()->{},true);try{block.enter();AudioFocusRequest request=ReflectionHelpers.getField(service.get(),"focus");assertEquals(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE,request.getFocusGain());assertEquals(volume,audio.getStreamVolume(AudioManager.STREAM_MUSIC));assertSame(same,ReflectionHelpers.getField(service.get(),"player"));block.stop();request=ReflectionHelpers.getField(service.get(),"focus");assertEquals(AudioManager.AUDIOFOCUS_GAIN,request.getFocusGain());}finally{block.stop();}}

}
